claim_compilation_result.query:
(
    df.map(
        prompt(
            "Identify whether the customer in the {dialog} complains about poor driver behavior",
            bool
        ).alias("complains_poor_driver_behavior")
    )
    .aggregate(
        [count_if(col("complains_poor_driver_behavior")).alias("count_poor_driver_behavior")]
    )
    .check(col("count_poor_driver_behavior").eq(785))
)
